#!/usr/bin/python3
"""Generate docs/TOOLS.md from the registered tool schemas (standard library only)."""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

from davinci_mcp import tools  # noqa: E402

OUTPUT = os.path.join(ROOT, "docs", "TOOLS.md")

HEADER = (
    "# DaVinci Resolve MCP tools\n"
    "\n"
    "Generated by scripts/gen_tools_doc.py — do not edit.\n"
)

SECTIONS = (
    ("read", "Read tools", "These tools only read state. They never change the project."),
    ("write", "Write tools", "These tools change Resolve or the project. Tools marked DESTRUCTIVE need `confirm: true`."),
    ("lua", "Open-ended", "This tool can run any Lua against the open project. Read first and ask before destructive changes."),
)


def _cell(text):
    return str(text).replace("|", "\\|").replace("\n", " ").strip()


def _type_text(spec):
    kind = spec.get("type")
    if isinstance(kind, list):
        return " / ".join(kind)
    return kind or "any"


def _constraints(spec):
    parts = []
    if "enum" in spec:
        parts.append("one of " + ", ".join("`%s`" % _json_scalar(v) for v in spec["enum"]))
    if "minimum" in spec:
        parts.append("min %s" % spec["minimum"])
    if "maximum" in spec:
        parts.append("max %s" % spec["maximum"])
    if "minLength" in spec:
        parts.append("minLength %s" % spec["minLength"])
    if "maxLength" in spec:
        parts.append("maxLength %s" % spec["maxLength"])
    if "minItems" in spec:
        parts.append("minItems %s" % spec["minItems"])
    if "maxItems" in spec:
        parts.append("maxItems %s" % spec["maxItems"])
    if "pattern" in spec:
        parts.append("pattern `%s`" % spec["pattern"])
    items = spec.get("items")
    if isinstance(items, dict) and items.get("type") not in (None, "object"):
        inner = _constraints(items)
        label = "items: " + _type_text(items)
        parts.append(label + (" (%s)" % inner if inner else ""))
    return "; ".join(parts)


def _json_scalar(value):
    if value is True:
        return "true"
    if value is False:
        return "false"
    return str(value)


def _rows(schema, prefix=""):
    required = set(schema.get("required") or [])
    rows = []
    for name, spec in (schema.get("properties") or {}).items():
        label = prefix + name
        rows.append("| `%s` | %s | %s | %s | %s |" % (
            label, _cell(_type_text(spec)), "yes" if name in required else "no",
            _cell(_constraints(spec)), _cell(spec.get("description", ""))))
        items = spec.get("items")
        if isinstance(items, dict) and items.get("properties"):
            rows.extend(_rows(items, label + "[]."))
    return rows


def _annotation_line(ann):
    if ann.get("readOnlyHint"):
        kind = "read-only"
    elif ann.get("destructiveHint"):
        kind = "DESTRUCTIVE"
    else:
        kind = "write"
    idem = "idempotent" if ann.get("idempotentHint") else "not idempotent"
    return "%s, %s" % (kind, idem)


def render():
    tools.load_all(strict=True)
    ordered = tools.ordered_tools()
    out = [HEADER]
    for group, title, blurb in SECTIONS:
        members = sorted((t for t in ordered if t.group == group), key=lambda t: t.name)
        out.append("## %s\n\n%s\n" % (title, blurb))
        for tool in members:
            out.append("### %s\n" % tool.name)
            out.append("%s\n" % _annotation_line(tool.annotations))
            out.append("%s\n" % tool.description)
            rows = _rows(tool.input_schema)
            if rows:
                out.append("| Argument | Type | Required | Constraints | Description |")
                out.append("|---|---|---|---|---|")
                out.extend(rows)
                out.append("")
            else:
                out.append("No arguments.\n")
    return "\n".join(out).rstrip("\n") + "\n"


def write(path=OUTPUT):
    text = render()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)
    return path


def main():
    print("wrote " + write())
    return 0


if __name__ == "__main__":
    sys.exit(main())
